export interface ProblemExample {
  input: string;
  output: string;
  explanation?: string;
}

export interface ProblemSolution {
  title: string;
  complexity: string;
  language: 'javascript' | 'python';
  code: string;
}

export interface TestCase {
  input: any[];
  expected: any;
  label: string;
}

export interface ProblemEditorial {
  approach: string;
  why_optimal: string;
  pitfalls: string;
}

export interface Problem {
  id: string;
  slug: string;
  title: string;
  topic: string;
  difficulty: 'Easy' | 'Medium' | 'Hard';
  pattern: string;
  statement: string;
  examples: ProblemExample[];
  constraints: string[];
  hints: string[];
  solutions: ProblemSolution[];
  starterCode: string;
  functionName: string;
  testCases: TestCase[];
  sequence?: number | null;
  prevSlug?: string | null;
  nextSlug?: string | null;
  editorial?: ProblemEditorial;
  readingLinks?: string[];
}


