        title: "Brute Force",
        complexity: "Time: O(n²) | Space: O(n)",
        language: "javascript",
        code: "function evalRPN(tokens) {\n  const items = tokens.slice();\n  function isOp(token) {\n    return token === '+' || token === '-' || token === '*' || token === '/';\n  }\n  while (items.length > 1) {\n    let opIdx = -1;\n    for (let i = 0; i < items.length; i++) {\n      if (isOp(items[i])) {\n        opIdx = i;\n        break;\n      }\n    }\n    if (opIdx < 1) {\n      break;\n    }\n    const a = Number(items[opIdx - 2]);\n    const b = Number(items[opIdx - 1]);\n    const op = items[opIdx];\n    let value = 0;\n    if (op === '+') {\n      value = a + b;\n    } else if (op === '-') {\n      value = a - b;\n    } else if (op === '*') {\n      value = a * b;\n    } else {\n      value = Math.trunc(a / b);\n    }\n    items.splice(opIdx - 2, 3, String(value));\n  }\n  return Number(items[items.length - 1]);\n}",
