        code: "function rotateRight(nums, k) {\n  if (nums.length <= 1 || k === 0) return nums.slice();\n  const arr = nums.slice();\n  const effectiveK = k % arr.length;\n  for (let step = 0; step < effectiveK; step++) {\n    const last = arr.pop();\n    arr.unshift(last);\n  }\n  return arr;\n}",
