        title: "Brute Force",
        complexity: "Time: O(n) | Space: O(h)",
        language: "javascript",
        code: "function lowestCommonAncestor(root, p, q) {\n  function findPath(i, target, path) {\n    if (i >= root.length || root[i] === null) return false;\n    path.push(root[i]);\n    if (root[i] === target) return true;\n    if (findPath(2 * i + 1, target, path) || findPath(2 * i + 2, target, path)) return true;\n    path.pop();\n    return false;\n  }\n  const pathP = [];\n  const pathQ = [];\n  findPath(0, p, pathP);\n  findPath(0, q, pathQ);\n  let lca = pathP[0];\n  const shared = Math.min(pathP.length, pathQ.length);\n  for (let k = 0; k < shared; k++) {\n    if (pathP[k] === pathQ[k]) {\n      lca = pathP[k];\n    } else {\n      break;\n    }\n  }\n  return lca;\n}",
