        code: "function findRedundantConnection(edges) {\n  let maxNode = 0;\n  for (let i = 0; i < edges.length; i++) {\n    if (edges[i][0] > maxNode) maxNode = edges[i][0];\n    if (edges[i][1] > maxNode) maxNode = edges[i][1];\n  }\n  const parent = [];\n  for (let i = 0; i <= maxNode; i++) parent[i] = i;\n  function find(x) {\n    while (parent[x] !== x) {\n      parent[x] = parent[parent[x]];\n      x = parent[x];\n    }\n    return x;\n  }\n  for (let i = 0; i < edges.length; i++) {\n    const u = edges[i][0];\n    const v = edges[i][1];\n    const ru = find(u);\n    const rv = find(v);\n    if (ru === rv) return [u, v];\n    parent[ru] = rv;\n  }\n  return [];\n}",
