        title: "Brute Force",
        complexity: "Time: O(n²) | Space: O(1)",
        language: "javascript",
        code: "function canCompleteCircuit(gas, cost) {\n  const n = gas.length;\n  for (let start = 0; start < n; start++) {\n    let tank = 0;\n    let possible = true;\n    for (let step = 0; step < n; step++) {\n      const idx = (start + step) % n;\n      tank += gas[idx] - cost[idx];\n      if (tank < 0) {\n        possible = false;\n        break;\n      }\n    }\n    if (possible) return start;\n  }\n  return -1;\n}",
